async function buy(){const status=document.getElementById('sale-status');try{const response=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const data=await response.json();if(!response.ok||!data.url)throw new Error(data.error||'Checkout is not enabled in this preview.');const url=new URL(data.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw new Error('Checkout destination could not be verified.');location.assign(url.href);}catch{const toast=document.getElementById('toast');toast.textContent='This is the owner preview. Purchases are not enabled yet. You can explore the working demo.';toast.hidden=false;if(status)status.textContent='Purchases are not enabled in this preview.';setTimeout(()=>toast.hidden=true,7000);}}
document.querySelectorAll('[data-buy]').forEach(button=>button.addEventListener('click',buy));
